class Solution {
public:
    int moves = 0;
    int extra(TreeNode* node) {
        if (!node) return 0;
        int l = extra(node->left);
        int r = extra(node->right);
        moves += abs(l) + abs(r);
        return node->val + l + r - 1;
    }
    int distributeCoins(TreeNode* root) {
        extra(root);
        return moves;
    }
};
